// WP-4.2 FSR 3.1 on Vulkan / render graph v2: see include/fuse/renderer/upscale_backends/fsr3/fsr3_gpu.hpp.
#include <fuse/renderer/upscale_backends/fsr3/fsr3_gpu.hpp>

#include <fuse/renderer/vk/allocator.hpp>
#include <fuse/renderer/vk/device.hpp>

#include <algorithm>
#include <cmath>
#include <cstring>

#if defined(FUSE_VULKAN_BACKEND)
#include <vulkan/vulkan.h>
#endif

// Generated by cmake/rp_wp42.cmake: kFsr3<Pass>Spv (vendored GLSL passes), kFsr3Convert{Slang,Glsl}Spv and the
// FUSE_FSR3_* availability macros.
#include "fsr3_spv.h"

namespace fuse::renderer::fsr3 {

namespace {
// VkFormat values.
constexpr u32 kR8Unorm = 9u, kR16Sfloat = 76u, kR16G16Sfloat = 83u, kR32Uint = 98u, kR32Sfloat = 100u,
              kR32G32Sfloat = 103u, kR8G8B8A8Unorm = 37u, kR16G16B16A16Sfloat = 97u, kR32G32B32A32Sfloat = 109u;
constexpr u32 kSlotStride = 768u; ///< main @0, SPD @256, RCAS @512 (256-byte aligned uniform ranges)
constexpr u32 kSpdOffset = 256u;
constexpr u32 kRcasOffset = 512u;
constexpr u32 kMaxSlots = 8u;

template <usize N>
Fsr3KernelCode code(const u32 (&spv)[N], const char* language) {
    return Fsr3KernelCode{spv, sizeof(spv), language};
}

#if defined(FUSE_VULKAN_BACKEND)
u32 mipCount(u32 w, u32 h) {
    u32 n = 1;
    u32 m = std::max(w, h);
    while (m > 1u) {
        m >>= 1u;
        ++n;
    }
    return n;
}
#endif
} // namespace

Fsr3KernelCode fsr3_kernel_code(Fsr3Pass pass, Fsr3KernelLanguage language) {
    switch (pass) {
    case Fsr3Pass::Convert:
#if defined(FUSE_FSR3_CONVERT_SLANG)
        if (language == Fsr3KernelLanguage::Auto || language == Fsr3KernelLanguage::Slang) {
            return code(kFsr3ConvertSlangSpv, "slang");
        }
#endif
#if defined(FUSE_FSR3_CONVERT_GLSL)
        if (language == Fsr3KernelLanguage::Auto || language == Fsr3KernelLanguage::Glsl) {
            return code(kFsr3ConvertGlslSpv, "glsl");
        }
#endif
        break;
#if defined(FUSE_FSR3_PASSES)
    case Fsr3Pass::PrepareInputs: return code(kFsr3PrepareInputsSpv, "glsl");
    case Fsr3Pass::LumaPyramid: return code(kFsr3LumaPyramidSpv, "glsl");
    case Fsr3Pass::ShadingChangePyramid: return code(kFsr3ShadingChangePyramidSpv, "glsl");
    case Fsr3Pass::ShadingChange: return code(kFsr3ShadingChangeSpv, "glsl");
    case Fsr3Pass::PrepareReactivity: return code(kFsr3PrepareReactivitySpv, "glsl");
    case Fsr3Pass::LumaInstability: return code(kFsr3LumaInstabilitySpv, "glsl");
    case Fsr3Pass::Accumulate: return code(kFsr3AccumulateSpv, "glsl");
    case Fsr3Pass::AccumulateSharpen: return code(kFsr3AccumulateSharpenSpv, "glsl");
    case Fsr3Pass::Rcas: return code(kFsr3RcasSpv, "glsl");
#endif
    default:
        break;
    }
    (void)language;
    return Fsr3KernelCode{};
}

Fsr3Capabilities queryFsr3Capabilities(const VulkanDevice* device) {
    Fsr3Capabilities c{};
#if defined(FUSE_VULKAN_BACKEND)
    if (device == nullptr || !device->isValid()) {
        return c;
    }
    for (u32 p = 0; p < kFsr3PassCount; ++p) {
        if (fsr3_kernel_code(static_cast<Fsr3Pass>(p)).words == nullptr) {
            c.reason = "FSR 3.1 passes not built (glslangValidator missing)";
            return c;
        }
    }
    const VkPhysicalDevice pd = static_cast<VkPhysicalDevice>(device->nativePhysicalDevice());
    VkPhysicalDeviceSubgroupProperties subgroup{};
    subgroup.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_SUBGROUP_PROPERTIES;
    VkPhysicalDeviceProperties2 props2{};
    props2.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_PROPERTIES_2;
    props2.pNext = &subgroup;
    vkGetPhysicalDeviceProperties2(pd, &props2);
    if ((subgroup.supportedStages & VK_SHADER_STAGE_COMPUTE_BIT) == 0u ||
        (subgroup.supportedOperations & VK_SUBGROUP_FEATURE_QUAD_BIT) == 0u) {
        c.reason = "compute subgroup quad operations missing (SPD pyramids)";
        return c;
    }
    const u32 storage[] = {kR8Unorm, kR16Sfloat, kR16G16Sfloat, kR32Uint, kR32Sfloat, kR32G32Sfloat, kR8G8B8A8Unorm,
                           kR16G16B16A16Sfloat, kR32G32B32A32Sfloat};
    for (const u32 f : storage) {
        VkFormatProperties fp{};
        vkGetPhysicalDeviceFormatProperties(pd, static_cast<VkFormat>(f), &fp);
        const VkFormatFeatureFlags need = VK_FORMAT_FEATURE_STORAGE_IMAGE_BIT | VK_FORMAT_FEATURE_SAMPLED_IMAGE_BIT;
        if ((fp.optimalTilingFeatures & need) != need) {
            c.reason = "a storage format of the FSR 3.1 resources is unsupported";
            return c;
        }
    }
    VkFormatProperties3 fp3{};
    fp3.sType = VK_STRUCTURE_TYPE_FORMAT_PROPERTIES_3;
    VkFormatProperties2 fp2{};
    fp2.sType = VK_STRUCTURE_TYPE_FORMAT_PROPERTIES_2;
    fp2.pNext = &fp3;
    vkGetPhysicalDeviceFormatProperties2(pd, static_cast<VkFormat>(kR16G16B16A16Sfloat), &fp2);
    if (device->info().apiVersion < VK_API_VERSION_1_3 ||
        (fp3.optimalTilingFeatures & VK_FORMAT_FEATURE_2_STORAGE_WRITE_WITHOUT_FORMAT_BIT) == 0u) {
        // rw_upscaled_output is declared without a format (StorageImageWriteWithoutFormat, allowed by Vulkan 1.3
        // per format through VK_FORMAT_FEATURE_2_STORAGE_WRITE_WITHOUT_FORMAT_BIT).
        c.reason = "RGBA16F storage write without format unsupported (Vulkan 1.3 format feature)";
        return c;
    }
    c.supported = true;
    c.reason = "ok";
#else
    (void)device;
    c.reason = "stub backend";
#endif
    return c;
}

Fsr3Gpu::~Fsr3Gpu() { destroy(); }

const Texture& Fsr3Gpu::outputImage() const { return m_res.images[kPhysOutput].tex; }

bool Fsr3Gpu::init(const Fsr3GpuDesc& desc) {
    destroy();
    m_desc = desc;
#if defined(FUSE_VULKAN_BACKEND)
    if (desc.allocator == nullptr || desc.framesInFlight == 0u || desc.framesInFlight > kMaxSlots ||
        !desc.maxResolution.valid() || !queryFsr3Capabilities(desc.device).supported) {
        return false;
    }
    const Fsr3KernelCode convert = fsr3_kernel_code(Fsr3Pass::Convert, desc.language);
    if (convert.words == nullptr) {
        return false;
    }
    m_initialized = true; // destroy() releases partial state from here on
    m_language = convert.language;
    m_retired.reserve(4);
    BufferDesc ring{};
    ring.size = static_cast<usize>(desc.framesInFlight) * kSlotStride;
    ring.usage = BufferUsage::Uniform;
    ring.memoryUsage = MemoryUsage::CpuToGpu;
    ring.name = "fsr3.constants";
    if (!m_desc.allocator->createBuffer(ring, m_ring) || m_ring.mapped == nullptr || !createPipelines() ||
        !createResources(m_res, desc.maxResolution)) {
        destroy();
        return false;
    }
    m_max = desc.maxResolution;
    fsr3_init_state(m_host, m_desc.settings, m_max.render_width, m_max.render_height, m_max.display_width, m_max.display_height);
    m_stats.rebuilds = 1u;
    return true;
#else
    return false;
#endif
}

void Fsr3Gpu::destroy() {
    if (!m_initialized) {
        return;
    }
    collectRetired(~0ull);
    destroyResources(m_res);
    destroyPipelines();
    if (m_ring.handle != nullptr) {
        m_desc.allocator->destroyBuffer(m_ring);
    }
    m_ring = Buffer{};
    m_retired.clear();
    m_max = UpscaleResolution{};
    m_resolution = UpscaleResolution{};
    m_host = Fsr3HostState{};
    m_setup = Fsr3FrameSetup{};
    m_begun = false;
    m_forceReset = false;
    m_language = "none";
    m_stats = Fsr3GpuStats{};
    m_initialized = false;
}

bool Fsr3Gpu::createPipelines() {
#if defined(FUSE_VULKAN_BACKEND)
    const VkDevice vk = static_cast<VkDevice>(m_desc.device->nativeHandle());
    // Static samplers of the Vulkan callbacks (binding 1000 point clamp, 1001 linear clamp).
    for (u32 i = 0; i < 2u; ++i) {
        VkSamplerCreateInfo s{};
        s.sType = VK_STRUCTURE_TYPE_SAMPLER_CREATE_INFO;
        s.magFilter = i == 0u ? VK_FILTER_NEAREST : VK_FILTER_LINEAR;
        s.minFilter = s.magFilter;
        s.mipmapMode = i == 0u ? VK_SAMPLER_MIPMAP_MODE_NEAREST : VK_SAMPLER_MIPMAP_MODE_LINEAR;
        s.addressModeU = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
        s.addressModeV = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
        s.addressModeW = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
        s.maxLod = VK_LOD_CLAMP_NONE;
        VkSampler sampler = VK_NULL_HANDLE;
        if (vkCreateSampler(vk, &s, nullptr, &sampler) != VK_SUCCESS) {
            return false;
        }
        m_samplers[i] = sampler;
    }
    u32 poolCounts[8] = {}; // indexed by VkDescriptorType 0..7
    for (u32 p = 0; p < kFsr3PassCount; ++p) {
        PassPipeline& pp = m_passes[p];
        const Fsr3KernelCode kc = fsr3_kernel_code(static_cast<Fsr3Pass>(p), m_desc.language);
        if (kc.words == nullptr || !reflect_spirv(kc.words, kc.bytes / 4u, pp.reflection)) {
            return false;
        }
        VkDescriptorSetLayoutBinding lb[kMaxBindings]{};
        VkSampler immutable[kMaxBindings]{};
        pp.bindingCount = 0;
        for (const SpirvBinding& b : pp.reflection.bindings) {
            Fsr3BindingTarget target{};
            if (b.set != 0u || pp.bindingCount >= kMaxBindings || !fsr3_resolve_binding(b.name.c_str(), target) ||
                target.resource == Fsr3Resource::LanczosLut) {
                // Unknown resource name (the vendored pass and the host tables disagree), or the Lanczos LUT, which
                // only the REPROJECT_USE_LANCZOS_TYPE=1 permutation reads (not built: no LUT resource is created).
                return false;
            }
            VkDescriptorType type = VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE;
            switch (b.kind) {
            case SpirvDescriptorKind::SampledImage: type = VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE; break;
            case SpirvDescriptorKind::StorageImage: type = VK_DESCRIPTOR_TYPE_STORAGE_IMAGE; break;
            case SpirvDescriptorKind::Sampler: type = VK_DESCRIPTOR_TYPE_SAMPLER; break;
            case SpirvDescriptorKind::UniformBuffer: type = VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER; break;
            case SpirvDescriptorKind::StorageBuffer: type = VK_DESCRIPTOR_TYPE_STORAGE_BUFFER; break;
            default: return false;
            }
            // The reflected kind must be what the name table says the resource is bound as.
            const bool kindOk = (target.kind == Fsr3BindingKind::Sampled && type == VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE) ||
                                (target.kind == Fsr3BindingKind::Storage && type == VK_DESCRIPTOR_TYPE_STORAGE_IMAGE) ||
                                (target.kind == Fsr3BindingKind::Sampler && type == VK_DESCRIPTOR_TYPE_SAMPLER) ||
                                (target.kind == Fsr3BindingKind::Uniform && type == VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER) ||
                                (target.kind == Fsr3BindingKind::StorageBuffer && type == VK_DESCRIPTOR_TYPE_STORAGE_BUFFER);
            if (!kindOk) {
                return false;
            }
            const u32 i = pp.bindingCount++;
            pp.bindings[i].binding = b.binding;
            pp.bindings[i].descriptorType = static_cast<u32>(type);
            pp.bindings[i].target = target;
            lb[i].binding = b.binding;
            lb[i].descriptorType = type;
            lb[i].descriptorCount = 1;
            lb[i].stageFlags = VK_SHADER_STAGE_COMPUTE_BIT;
            if (type == VK_DESCRIPTOR_TYPE_SAMPLER) {
                immutable[i] = static_cast<VkSampler>(m_samplers[target.resource == Fsr3Resource::SamplerPoint ? 0 : 1]);
                lb[i].pImmutableSamplers = &immutable[i];
            }
            poolCounts[static_cast<u32>(type)] += m_desc.framesInFlight;
        }
        VkDescriptorSetLayoutCreateInfo sl{};
        sl.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO;
        sl.bindingCount = pp.bindingCount;
        sl.pBindings = lb;
        VkDescriptorSetLayout setLayout = VK_NULL_HANDLE;
        if (vkCreateDescriptorSetLayout(vk, &sl, nullptr, &setLayout) != VK_SUCCESS) {
            return false;
        }
        pp.setLayout = setLayout;
        pp.pushBytes = pp.reflection.pushConstantBytes;
        VkPushConstantRange range{VK_SHADER_STAGE_COMPUTE_BIT, 0, pp.pushBytes};
        VkPipelineLayoutCreateInfo pl{};
        pl.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
        pl.setLayoutCount = 1;
        pl.pSetLayouts = &setLayout;
        pl.pushConstantRangeCount = pp.pushBytes != 0u ? 1u : 0u;
        pl.pPushConstantRanges = &range;
        VkPipelineLayout layout = VK_NULL_HANDLE;
        if (vkCreatePipelineLayout(vk, &pl, nullptr, &layout) != VK_SUCCESS) {
            return false;
        }
        pp.layout = layout;
        VkShaderModuleCreateInfo mi{};
        mi.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
        mi.codeSize = kc.bytes;
        mi.pCode = kc.words;
        VkShaderModule module = VK_NULL_HANDLE;
        if (vkCreateShaderModule(vk, &mi, nullptr, &module) != VK_SUCCESS) {
            return false;
        }
        VkComputePipelineCreateInfo ci{};
        ci.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
        ci.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
        ci.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
        ci.stage.module = module;
        ci.stage.pName = "main";
        ci.layout = layout;
        VkPipeline pipeline = VK_NULL_HANDLE;
        const VkResult result = vkCreateComputePipelines(vk, VK_NULL_HANDLE, 1, &ci, nullptr, &pipeline);
        vkDestroyShaderModule(vk, module, nullptr);
        if (result != VK_SUCCESS) {
            return false;
        }
        pp.pipeline = pipeline;
    }
    VkDescriptorPoolSize sizes[8]{};
    u32 sizeCount = 0;
    for (u32 t = 0; t < 8u; ++t) {
        if (poolCounts[t] != 0u) {
            sizes[sizeCount++] = VkDescriptorPoolSize{static_cast<VkDescriptorType>(t), poolCounts[t]};
        }
    }
    VkDescriptorPoolCreateInfo pi{};
    pi.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO;
    pi.maxSets = kFsr3PassCount * m_desc.framesInFlight;
    pi.poolSizeCount = sizeCount;
    pi.pPoolSizes = sizes;
    VkDescriptorPool pool = VK_NULL_HANDLE;
    if (vkCreateDescriptorPool(vk, &pi, nullptr, &pool) != VK_SUCCESS) {
        return false;
    }
    m_pool = pool;
    for (u32 p = 0; p < kFsr3PassCount; ++p) {
        for (u32 s = 0; s < m_desc.framesInFlight; ++s) {
            VkDescriptorSetLayout setLayout = static_cast<VkDescriptorSetLayout>(m_passes[p].setLayout);
            VkDescriptorSetAllocateInfo ai{};
            ai.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO;
            ai.descriptorPool = pool;
            ai.descriptorSetCount = 1;
            ai.pSetLayouts = &setLayout;
            VkDescriptorSet set = VK_NULL_HANDLE;
            if (vkAllocateDescriptorSets(vk, &ai, &set) != VK_SUCCESS) {
                return false;
            }
            m_passes[p].sets[s] = set;
        }
    }
    return true;
#else
    return false;
#endif
}

void Fsr3Gpu::destroyPipelines() {
#if defined(FUSE_VULKAN_BACKEND)
    const VkDevice vk = static_cast<VkDevice>(m_desc.device->nativeHandle());
    if (m_pool != nullptr) {
        vkDestroyDescriptorPool(vk, static_cast<VkDescriptorPool>(m_pool), nullptr);
    }
    for (PassPipeline& pp : m_passes) {
        if (pp.pipeline != nullptr) {
            vkDestroyPipeline(vk, static_cast<VkPipeline>(pp.pipeline), nullptr);
        }
        if (pp.layout != nullptr) {
            vkDestroyPipelineLayout(vk, static_cast<VkPipelineLayout>(pp.layout), nullptr);
        }
        if (pp.setLayout != nullptr) {
            vkDestroyDescriptorSetLayout(vk, static_cast<VkDescriptorSetLayout>(pp.setLayout), nullptr);
        }
        pp = PassPipeline{};
    }
    for (void*& s : m_samplers) {
        if (s != nullptr) {
            vkDestroySampler(vk, static_cast<VkSampler>(s), nullptr);
        }
        s = nullptr;
    }
#endif
    m_pool = nullptr;
}

bool Fsr3Gpu::createResources(Resources& r, const UpscaleResolution& max) {
    r = Resources{};
    r.max = max;
#if defined(FUSE_VULKAN_BACKEND)
    const u32 rw = max.render_width, rh = max.render_height, dw = max.display_width, dh = max.display_height;
    const u32 hw = std::max(rw / 2u, 1u), hh = std::max(rh / 2u, 1u); // maxRenderSizeDiv2
    struct Spec {
        Phys phys;
        u32 format, w, h, mips;
        const char* name;
    };
    const Spec specs[] = {
        {kPhysDepth, kR32Sfloat, rw, rh, 1, "fsr3.input_depth"},
        {kPhysMotion, kR32G32Sfloat, rw, rh, 1, "fsr3.input_motion"},
        {kPhysExposure, kR32G32Sfloat, 1, 1, 1, "fsr3.exposure"},
        {kPhysDefaultReactive, kR8Unorm, 1, 1, 1, "fsr3.default_reactivity"},
        {kPhysFrameInfo, kR32G32B32A32Sfloat, 1, 1, 1, "fsr3.frame_info"},
        {kPhysRecon, kR32Uint, rw, rh, 1, "fsr3.reconstructed_prev_nearest_depth"},
        {kPhysDilatedMotion, kR16G16Sfloat, rw, rh, 1, "fsr3.dilated_motion"},
        {kPhysDilatedDepth, kR32Sfloat, rw, rh, 1, "fsr3.dilated_depth"},
        {kPhysAccum0, kR8Unorm, rw, rh, 1, "fsr3.accumulation1"},
        {kPhysAccum1, kR8Unorm, rw, rh, 1, "fsr3.accumulation2"},
        {kPhysUpscaled0, kR16G16B16A16Sfloat, dw, dh, 1, "fsr3.internal_upscaled1"},
        {kPhysUpscaled1, kR16G16B16A16Sfloat, dw, dh, 1, "fsr3.internal_upscaled2"},
        {kPhysLumaHistory0, kR16G16B16A16Sfloat, rw, rh, 1, "fsr3.luma_history1"},
        {kPhysLumaHistory1, kR16G16B16A16Sfloat, rw, rh, 1, "fsr3.luma_history2"},
        {kPhysLuma0, kR16Sfloat, rw, rh, 1, "fsr3.luma1"},
        {kPhysLuma1, kR16Sfloat, rw, rh, 1, "fsr3.luma2"},
        {kPhysIntermediate, kR16Sfloat, rw, rh, 1, "fsr3.intermediate_fp16x1"},
        {kPhysFarthestMip1, kR16Sfloat, hw, hh, 1, "fsr3.farthest_depth_mip1"},
        {kPhysShadingChange, kR8Unorm, hw, hh, 1, "fsr3.shading_change"},
        {kPhysSpdMips, kR16G16Sfloat, hw, hh, mipCount(hw, hh), "fsr3.spd_mips"},
        {kPhysSpdAtomic, kR32Uint, 1, 1, 1, "fsr3.spd_atomic"},
        {kPhysNewLocks, kR8Unorm, dw, dh, 1, "fsr3.new_locks"},
        {kPhysDilatedReactive, kR8G8B8A8Unorm, rw, rh, 1, "fsr3.dilated_reactive_masks"},
        {kPhysOutput, kR16G16B16A16Sfloat, dw, dh, 1, "fsr3.output"},
    };
    static_assert(kPhysCount <= kFsr3MaxImages, "Fsr3GraphRefs::images");
    bool ok = true;
    for (const Spec& s : specs) {
        if (!ok) {
            break;
        }
        Image& img = r.images[s.phys];
        TextureDesc d{};
        d.width = s.w;
        d.height = s.h;
        d.mipLevels = s.mips;
        d.format = static_cast<GpuFormat>(s.format);
        u32 usage = static_cast<u32>(ImageUsage::Sampled) | static_cast<u32>(ImageUsage::TransferDst) |
                    static_cast<u32>(ImageUsage::TransferSrc);
        usage |= static_cast<u32>(ImageUsage::Storage);
        d.usage = static_cast<ImageUsage>(usage);
        d.name = s.name;
        ok = m_desc.allocator->createImage(d, img.tex);
        img.format = s.format;
        img.width = s.w;
        img.height = s.h;
        img.mips = s.mips;
        img.name = s.name;
    }
    if (ok) {
        const VkDevice vk = static_cast<VkDevice>(m_desc.device->nativeHandle());
        const Image& spd = r.images[kPhysSpdMips];
        for (u32 m = 0; m < kSpdViews && ok; ++m) {
            VkImageViewCreateInfo vi{};
            vi.sType = VK_STRUCTURE_TYPE_IMAGE_VIEW_CREATE_INFO;
            vi.image = static_cast<VkImage>(spd.tex.image);
            vi.viewType = VK_IMAGE_VIEW_TYPE_2D;
            vi.format = static_cast<VkFormat>(spd.format);
            vi.subresourceRange = {VK_IMAGE_ASPECT_COLOR_BIT, std::min(m, spd.mips - 1u), 1, 0, 1};
            VkImageView view = VK_NULL_HANDLE;
            ok = vkCreateImageView(vk, &vi, nullptr, &view) == VK_SUCCESS;
            r.spdViews[m] = view;
        }
    }
    if (!ok) {
        destroyResources(r);
    }
    return ok;
#else
    return false;
#endif
}

void Fsr3Gpu::destroyResources(Resources& r) {
#if defined(FUSE_VULKAN_BACKEND)
    const VkDevice vk = m_desc.device != nullptr ? static_cast<VkDevice>(m_desc.device->nativeHandle()) : VK_NULL_HANDLE;
    for (void*& v : r.spdViews) {
        if (v != nullptr && vk != VK_NULL_HANDLE) {
            vkDestroyImageView(vk, static_cast<VkImageView>(v), nullptr);
        }
        v = nullptr;
    }
#endif
    for (Image& img : r.images) {
        if (img.tex.image != nullptr) {
            m_desc.allocator->destroyImage(img.tex);
        }
    }
    r = Resources{};
}

u32 Fsr3Gpu::collectRetired(u64 completedSerial) {
    u32 collected = 0;
    usize keep = 0;
    for (usize i = 0; i < m_retired.size(); ++i) {
        if (m_retired[i].serial > completedSerial) {
            m_retired[keep++] = m_retired[i];
            continue;
        }
        destroyResources(m_retired[i].res);
        ++collected;
    }
    m_retired.resize(keep);
    m_stats.retired = static_cast<u32>(m_retired.size());
    return collected;
}

bool Fsr3Gpu::beginFrame(u64 frameSerial, const Fsr3GpuFrameDesc& frame) {
    m_begun = false;
    m_stats.passes = 0;
    m_stats.clears = 0;
    m_stats.reset = false;
    const UpscaleResolution& r = frame.resolution;
    if (!m_initialized || !r.valid() || !std::isfinite(frame.exposure) || !(frame.exposure > 0.f) ||
        !std::isfinite(frame.jitter_px.x) || !std::isfinite(frame.jitter_px.y) || std::fabs(frame.jitter_px.x) > 0.5f ||
        std::fabs(frame.jitter_px.y) > 0.5f) {
        return false;
    }
    if (r.render_width > m_max.render_width || r.render_height > m_max.render_height || r.display_width > m_max.display_width ||
        r.display_height > m_max.display_height) {
        // Grow: new resources sized for the new maximum, old ones retired once this frame completes.
        UpscaleResolution grown{};
        grown.render_width = std::max(r.render_width, m_max.render_width);
        grown.render_height = std::max(r.render_height, m_max.render_height);
        grown.display_width = std::max(r.display_width, m_max.display_width);
        grown.display_height = std::max(r.display_height, m_max.display_height);
        Resources fresh{};
        if (!createResources(fresh, grown)) {
            return false;
        }
        Retired old{};
        old.res = m_res;
        old.serial = frameSerial;
        m_retired.push_back(old);
        m_res = fresh;
        m_max = grown;
        fsr3_init_state(m_host, m_desc.settings, m_max.render_width, m_max.render_height, m_max.display_width,
                        m_max.display_height);
        ++m_stats.rebuilds;
        m_stats.retired = static_cast<u32>(m_retired.size());
    }
    Fsr3FrameParams p{};
    p.resolution = r;
    p.jitter_px = frame.debug_flip_jitter_sign ? math::Vec2(-frame.jitter_px.x, -frame.jitter_px.y) : frame.jitter_px;
    p.exposure = frame.exposure;
    p.pre_exposure = frame.pre_exposure;
    p.frame_time_s = frame.frame_time_s;
    p.reset = frame.reset_history || m_forceReset;
    p.near_plane = frame.camera.near_plane;
    p.far_plane = frame.camera.far_plane;
    p.vertical_fov_rad = frame.camera.vertical_fov_rad;
    p.sharpen = frame.sharpen;
    p.sharpness = frame.sharpness;
    if (!fsr3_setup_frame(m_host, m_desc.settings, p, m_setup)) {
        return false;
    }
    m_forceReset = false;
    m_frame = frame;
    m_resolution = r;
    m_slot = static_cast<u32>(frameSerial % m_desc.framesInFlight);
    m_slotOffset = static_cast<u64>(m_slot) * kSlotStride;
    u8* base = static_cast<u8*>(m_ring.mapped) + m_slotOffset;
    std::memcpy(base, &m_setup.constants, sizeof(m_setup.constants));
    std::memcpy(base + kSpdOffset, &m_setup.spd, sizeof(m_setup.spd));
    std::memcpy(base + kRcasOffset, &m_setup.rcas, sizeof(m_setup.rcas));
    m_stats.reset = m_setup.resetAccumulation;
    ++m_stats.frames;
    m_begun = true;
    return true;
}

Fsr3GraphRefs Fsr3Gpu::importInto(rg::Graph& graph) {
    Fsr3GraphRefs refs{};
    if (!m_initialized) {
        return refs;
    }
    for (u32 i = 0; i < kPhysCount; ++i) {
        Image& img = m_res.images[i];
        if (img.tex.image == nullptr) {
            continue;
        }
        rg::ImportedImage ii{};
        ii.image = img.tex.image;
        ii.view = img.tex.view;
        ii.format = img.format;
        ii.width = img.width;
        ii.height = img.height;
        ii.mipLevels = img.mips;
        ii.initialLayout = img.layout;
        ii.initialQueue = img.queue;
        // Every mip ends in one layout, so the subresource-0 tracker describes the whole image next frame.
        ii.finalLayout = 1u; // VK_IMAGE_LAYOUT_GENERAL
        ii.layoutTracker = &img.layout;
        ii.queueTracker = &img.queue;
        ii.name = img.name;
        refs.images[i] = graph.importImage(ii);
    }
    refs.output = refs.images[kPhysOutput];
    return refs;
}

u32 Fsr3Gpu::physFor(Fsr3Resource resource, bool storage) const {
    // fsr3upscalerDispatch: odd frames read the *_2 surfaces and write the *_1 ones.
    const bool odd = m_setup.oddFrame;
    switch (resource) {
    case Fsr3Resource::InputDepth: return kPhysDepth;
    case Fsr3Resource::InputMotion: return kPhysMotion;
    case Fsr3Resource::InputExposure: return kPhysExposure;
    case Fsr3Resource::InputReactive: return m_hasReactive ? kPhysCount : kPhysDefaultReactive;
    case Fsr3Resource::InputTransparency: return m_hasTransparency ? kPhysCount : kPhysDefaultReactive;
    case Fsr3Resource::FrameInfo: return kPhysFrameInfo;
    case Fsr3Resource::ReconstructedPrevNearestDepth: return kPhysRecon;
    case Fsr3Resource::DilatedMotion: return kPhysDilatedMotion;
    case Fsr3Resource::DilatedDepth: return kPhysDilatedDepth;
    case Fsr3Resource::Accumulation: return (storage ? !odd : odd) ? kPhysAccum1 : kPhysAccum0;
    case Fsr3Resource::InternalUpscaled: return (storage ? !odd : odd) ? kPhysUpscaled1 : kPhysUpscaled0;
    case Fsr3Resource::RcasInput: return odd ? kPhysUpscaled0 : kPhysUpscaled1; // this frame's UAV image
    case Fsr3Resource::LumaHistory: return (storage ? !odd : odd) ? kPhysLumaHistory1 : kPhysLumaHistory0;
    case Fsr3Resource::CurrentLuma: return odd ? kPhysLuma1 : kPhysLuma0;
    case Fsr3Resource::PreviousLuma: return odd ? kPhysLuma0 : kPhysLuma1;
    case Fsr3Resource::Intermediate: return kPhysIntermediate;
    case Fsr3Resource::FarthestDepthMip1: return kPhysFarthestMip1;
    case Fsr3Resource::ShadingChange: return kPhysShadingChange;
    case Fsr3Resource::SpdMips: return kPhysSpdMips;
    case Fsr3Resource::SpdAtomic: return kPhysSpdAtomic;
    case Fsr3Resource::NewLocks: return kPhysNewLocks;
    case Fsr3Resource::DilatedReactiveMasks: return kPhysDilatedReactive;
    case Fsr3Resource::UpscaledOutput: return kPhysOutput;
    default: return kPhysCount;
    }
}

rg::TextureRef Fsr3Gpu::refFor(const Fsr3GraphRefs& refs, const Fsr3GpuInputs& inputs, Fsr3Resource resource, bool storage) const {
    switch (resource) {
    case Fsr3Resource::InputColor: return inputs.color;
    case Fsr3Resource::InputReactive:
        if (m_hasReactive) {
            return inputs.reactive;
        }
        break;
    case Fsr3Resource::InputTransparency:
        if (m_hasTransparency) {
            return inputs.transparency;
        }
        break;
    default:
        break;
    }
    const u32 phys = physFor(resource, storage);
    return phys < kPhysCount ? refs.images[phys] : rg::TextureRef{};
}

void Fsr3Gpu::addPasses(rg::Graph& graph, const Fsr3GraphRefs& refs, const Fsr3GpuInputs& inputs) {
    if (!m_initialized || !m_begun || !refs.output.valid() || !inputs.color.valid() || !inputs.depth.valid() ||
        !inputs.motion.valid()) {
        return;
    }
    m_begun = false;
    m_inputs = inputs;
    m_refs = refs;
    m_hasReactive = inputs.reactive.valid();
    m_hasTransparency = inputs.transparency.valid();

    // Clears (the SDK's clear jobs). First use of fresh resources: every image (FUSE: deterministic history, the
    // SDK leaves the never-read-before-written ones uninitialised). Reset: the accumulation being read, the SPD
    // mips and the frame info. Every frame: reconstructed previous nearest depth, the SPD atomic counter and the
    // SPD mips.
    ClearRecord& c = m_clear;
    c = ClearRecord{};
    c.self = this;
    auto clear = [&](u32 phys) {
        for (u32 i = 0; i < c.count; ++i) {
            if (c.phys[i] == phys) {
                return;
            }
        }
        c.phys[c.count] = static_cast<u8>(phys);
        c.refs[c.count] = refs.images[phys];
        ++c.count;
    };
    if (!m_res.cleared) {
        for (u32 i = 0; i < kPhysCount; ++i) {
            if (i != kPhysOutput && refs.images[i].valid()) {
                clear(i);
            }
        }
        m_res.cleared = true;
    }
    if (m_setup.resetAccumulation) {
        clear(physFor(Fsr3Resource::Accumulation, false));
        clear(kPhysSpdMips);
        clear(kPhysFrameInfo);
    }
    clear(kPhysRecon);
    clear(kPhysSpdAtomic);
    clear(kPhysSpdMips);
    {
        rg::PassBuilder pass = graph.addPass("fsr3.clear", &Fsr3Gpu::recordClear, &m_clear);
        for (u32 i = 0; i < c.count; ++i) {
            pass.use(c.refs[i], rg::Access::TransferDst);
        }
    }
    m_stats.clears = c.count;

    addPass(graph, refs, inputs, Fsr3Pass::Convert);
    addPass(graph, refs, inputs, Fsr3Pass::PrepareInputs);
    addPass(graph, refs, inputs, Fsr3Pass::LumaPyramid);
    addPass(graph, refs, inputs, Fsr3Pass::ShadingChangePyramid);
    addPass(graph, refs, inputs, Fsr3Pass::ShadingChange);
    addPass(graph, refs, inputs, Fsr3Pass::PrepareReactivity);
    addPass(graph, refs, inputs, Fsr3Pass::LumaInstability);
    if (m_frame.sharpen) {
        addPass(graph, refs, inputs, Fsr3Pass::AccumulateSharpen);
        addPass(graph, refs, inputs, Fsr3Pass::Rcas);
    } else {
        addPass(graph, refs, inputs, Fsr3Pass::Accumulate);
    }
}

void Fsr3Gpu::addPass(rg::Graph& graph, const Fsr3GraphRefs& refs, const Fsr3GpuInputs& inputs, Fsr3Pass pass) {
    const u32 p = static_cast<u32>(pass);
    PassRecord& rec = m_records[p];
    rec.self = this;
    rec.pass = pass;
    rec.groups[0] = std::max(m_setup.groups[p][0], 1u);
    rec.groups[1] = std::max(m_setup.groups[p][1], 1u);
    rg::PassBuilder b = graph.addPass(fsr3_pass_name(pass), &Fsr3Gpu::recordPass, &rec);
    const PassPipeline& pp = m_passes[p];
    // One declaration per graph resource (the SPD mip views of one image collapse into one storage use).
    rg::TextureRef seen[kMaxBindings];
    u32 seenCount = 0;
    const u64 rn = static_cast<u64>(m_resolution.render_width) * m_resolution.render_height;
    for (u32 i = 0; i < pp.bindingCount; ++i) {
        const Fsr3BindingTarget& t = pp.bindings[i].target;
        if (t.kind == Fsr3BindingKind::StorageBuffer) {
            if (t.resource == Fsr3Resource::SourceDepth) {
                b.use(inputs.depth, rg::Access::StorageRead, rg::BufferRange{0, rn * 4u}, rg::kStageCompute);
            } else {
                b.use(inputs.motion, rg::Access::StorageRead, rg::BufferRange{0, rn * 8u}, rg::kStageCompute);
            }
            continue;
        }
        if (t.kind != Fsr3BindingKind::Sampled && t.kind != Fsr3BindingKind::Storage) {
            continue;
        }
        const bool storage = t.kind == Fsr3BindingKind::Storage;
        const rg::TextureRef ref = refFor(refs, inputs, t.resource, storage);
        bool dup = false;
        for (u32 k = 0; k < seenCount; ++k) {
            dup = dup || seen[k].id == ref.id;
        }
        if (dup || !ref.valid()) {
            continue;
        }
        seen[seenCount++] = ref;
        b.use(ref, storage ? rg::Access::StorageReadWrite : rg::Access::SampledRead, {}, rg::kStageCompute);
    }
    ++m_stats.passes;
}

void Fsr3Gpu::recordClear(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const ClearRecord& c = *static_cast<const ClearRecord*>(user);
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    const Fsr3Gpu& self = *c.self;
    for (u32 i = 0; i < c.count; ++i) {
        const u32 phys = c.phys[i];
        VkClearColorValue value{};
        if (phys == kPhysFrameInfo && self.m_setup.resetAccumulation) {
            // "Clear Frame Info": auto-exposure state (-1, 1, 0, 0).
            value.float32[0] = -1.f;
            value.float32[1] = 1.f;
        }
        // Reconstructed previous nearest depth: the inverted-depth clear value 0 (0 bits for the R32_UINT image);
        // everything else 0.
        const VkImageSubresourceRange range{VK_IMAGE_ASPECT_COLOR_BIT, 0, VK_REMAINING_MIP_LEVELS, 0, 1};
        vkCmdClearColorImage(cmd, static_cast<VkImage>(context.image(c.refs[i])), VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL, &value, 1,
                             &range);
    }
#else
    (void)context;
    (void)user;
#endif
}

void Fsr3Gpu::recordPass(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const PassRecord& rec = *static_cast<const PassRecord*>(user);
    const Fsr3Gpu& self = *rec.self;
    const PassPipeline& pp = self.m_passes[static_cast<u32>(rec.pass)];
    const VkDevice vk = static_cast<VkDevice>(self.m_desc.device->nativeHandle());
    VkDescriptorSet set = static_cast<VkDescriptorSet>(pp.sets[self.m_slot]);
    VkWriteDescriptorSet writes[kMaxBindings]{};
    VkDescriptorImageInfo images[kMaxBindings]{};
    VkDescriptorBufferInfo buffers[kMaxBindings]{};
    u32 count = 0;
    const u64 rn = static_cast<u64>(self.m_resolution.render_width) * self.m_resolution.render_height;
    const VkBuffer ring = static_cast<VkBuffer>(self.m_ring.handle);
    for (u32 i = 0; i < pp.bindingCount; ++i) {
        const PassBinding& pb = pp.bindings[i];
        const Fsr3BindingTarget& t = pb.target;
        if (t.kind == Fsr3BindingKind::Sampler) {
            continue; // immutable
        }
        VkWriteDescriptorSet& w = writes[count];
        w.sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET;
        w.dstSet = set;
        w.dstBinding = pb.binding;
        w.descriptorCount = 1;
        w.descriptorType = static_cast<VkDescriptorType>(pb.descriptorType);
        if (t.kind == Fsr3BindingKind::Uniform) {
            const u64 offset = t.resource == Fsr3Resource::ConstantsSpd ? kSpdOffset
                               : t.resource == Fsr3Resource::ConstantsRcas ? kRcasOffset
                                                                           : 0u;
            const u64 size = t.resource == Fsr3Resource::ConstantsSpd    ? sizeof(Fsr3SpdConstants)
                             : t.resource == Fsr3Resource::ConstantsRcas ? sizeof(Fsr3RcasConstants)
                                                                         : sizeof(Fsr3UpscalerConstants);
            buffers[count] = VkDescriptorBufferInfo{ring, self.m_slotOffset + offset, size};
            w.pBufferInfo = &buffers[count];
        } else if (t.kind == Fsr3BindingKind::StorageBuffer) {
            const bool depth = t.resource == Fsr3Resource::SourceDepth;
            const rg::BufferRef ref = depth ? self.m_inputs.depth : self.m_inputs.motion;
            buffers[count] = VkDescriptorBufferInfo{static_cast<VkBuffer>(context.buffer(ref)), 0, rn * (depth ? 4u : 8u)};
            w.pBufferInfo = &buffers[count];
        } else {
            const bool storage = t.kind == Fsr3BindingKind::Storage;
            VkImageView view = VK_NULL_HANDLE;
            if (t.resource == Fsr3Resource::SpdMips && storage) {
                view = static_cast<VkImageView>(self.m_res.spdViews[std::min<u32>(t.mip, kSpdViews - 1u)]);
            } else {
                view = static_cast<VkImageView>(context.imageView(self.refFor(self.m_refs, self.m_inputs, t.resource, storage)));
            }
            images[count] = VkDescriptorImageInfo{VK_NULL_HANDLE, view,
                                                  storage ? VK_IMAGE_LAYOUT_GENERAL : VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL};
            w.pImageInfo = &images[count];
        }
        ++count;
    }
    vkUpdateDescriptorSets(vk, count, writes, 0, nullptr);
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipeline>(pp.pipeline));
    vkCmdBindDescriptorSets(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipelineLayout>(pp.layout), 0, 1, &set, 0, nullptr);
    if (rec.pass == Fsr3Pass::Convert) {
        Fsr3ConvertPush push{};
        push.renderW = self.m_resolution.render_width;
        push.renderH = self.m_resolution.render_height;
        push.nearPlane = self.m_frame.camera.near_plane;
        push.farPlane = self.m_frame.camera.far_plane;
        push.exposure = self.m_frame.exposure;
        vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(pp.layout), VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(push), &push);
    }
    vkCmdDispatch(cmd, rec.groups[0], rec.groups[1], 1u);
#else
    (void)context;
    (void)user;
#endif
}

} // namespace fuse::renderer::fsr3
